webhook_echo.code:
import { workflow, trigger, node } from '@n8n/workflow-sdk';

const webhookTrigger = trigger({
  type: 'n8n-nodes-base.webhook',
  version: 2.1,
  config: { name: 'Webhook', position: [240, 200] },
  output: [{ body: { message: 'Hello!' } }]
});

const setResponse = node({
  type: 'n8n-nodes-base.set',
  version: 3.4,
  config: { name: 'Set Response', position: [640, 200], parameters: { values: { string: [{ name: 'message', value: 'Hello from n8n!' }] } } },
  output: [{ message: 'Hello from n8n!' }]
});

export default workflow('webhook-echo', 'Webhook Echo')
  .add(webhookTrigger)
  .to(setResponse);

