webhook_filter.code:
import { workflow, trigger, node } from '@n8n/workflow-sdk';

const filterTrigger = trigger({
  type: 'n8n-nodes-base.webhook',
  version: 2.1,
  config: { name: 'Trigger', position: [240, 200] },
  output: [{ body: { severity: 'high' } }]
});

const ifNode = node({
  type: 'n8n-nodes-base.if',
  version: 2.1,
  config: { name: 'Check Severity', position: [540, 200], parameters: { conditions: { options: { caseSensitive: true, looseType: false }, conditions: [{ id: 'cond1', leftValue: '={{ .severity }}', rightValue: 'high', operator: { type: 'string', operation: 'equals' } }] } } },
  output: [{ matched: true }]
});

const emailNode = node({
  type: 'n8n-nodes-base.emailSend',
  version: 1.2,
  config: { name: 'Send Email', position: [840, 200], parameters: { to: 'admin@example.com', subject: 'High Severity Alert', text: 'A high severity alert was triggered.' } },
  output: [{ sent: true }]
});

export default workflow('webhook-filter', 'Webhook Filter')
  .add(filterTrigger)
  .to(ifNode)
  .to(emailNode);

